    'piano_learners' => [
        'meta_title' => 'Harmoniva para quem estuda piano',
        'meta_description' => 'Eleve seus estudos de piano com treinamento auditivo: reconheça intervalos, acordes e melodias de ouvido e toque com liberdade musical.',
