    'ear_guide' => [
        'meta_title' => 'O guia completo de treinamento auditivo',
        'meta_description' => 'Guia completo de treinamento auditivo, capítulo a capítulo: do básico às técnicas avançadas — o que praticar, como e com que resultado.',
        'jsonld_headline' => 'O guia completo de treinamento auditivo',
        'jsonld_description' => 'Um guia abrangente, capítulo a capítulo, sobre treinamento auditivo — do básico absoluto às técnicas avançadas.',
        'jsonld_about' => 'Treinamento auditivo',
        'jsonld_home' => 'Início',
        'hero_badge' => 'Guia gratuito',
        'hero_title' => 'O guia completo de treinamento auditivo',
        'hero_subtitle' => 'Do seu primeiro intervalo ao ditado melódico avançado — tudo o que você precisa para construir um ouvido musical de primeira, explicado com clareza e na prática.',
        'hero_stat_1' => '25 min de leitura',
