        'level_int_title' => 'Intermediário',
        'level_int_period' => '3–12 meses',
        'level_int_1' => 'Intervalos harmônicos',
        'level_int_2' => 'Todos os tipos de acorde + inversões',
        'level_int_3' => 'Identificação de escalas e modos',
        'level_int_4' => 'Ditado rítmico',
        'level_adv_title' => 'Avançado',
        'level_adv_period' => '1 ano ou mais',
        'level_adv_1' => 'Ditado melódico',
        'level_adv_2' => 'Progressões de acordes complexas',
        'level_adv_3' => 'Domínio do ouvido relativo',
        'level_adv_4' => 'Harmonia modal',
        'ch6_takeaway' => 'O progresso não é linear. Os saltos costumam vir de repente, depois de platôs. Confie no processo, apareça todo dia, e os resultados vêm.',
        'final_title' => 'Pronto para colocar este guia em prática?',
        'final_subtitle' => 'A Harmoniva facilita seguir exatamente o tipo de prática estruturada e adaptativa que este guia recomenda — desde o primeiro dia e totalmente de graça.',
        'final_button_1' => 'Comece a treinar grátis',
        'final_button_2' => 'Ver o Caminho de aprendizagem',
