        'prob_li2' => 'raspar, rastrear ou extrair sistematicamente conteúdo do Serviço sem autorização expressa por escrito',
        'prob_li3' => 'fazer engenharia reversa, descompilar ou tentar derivar o código-fonte do Serviço',
        'prob_li4' => 'tentar obter acesso não autorizado a qualquer parte do Serviço, à sua infraestrutura ou a contas de outros usuários',
