        'prights_li1' => '<strong>Consulta</strong>: solicitar uma cópia das informações pessoais que coletamos do seu filho.',
        'prights_li2' => '<strong>Correção</strong>: solicitar a correção de informações incorretas.',
        'prights_li3' => '<strong>Exclusão</strong>: solicitar que apaguemos as informações pessoais e a conta do seu filho.',
        'prights_li4' => '<strong>Retirada do consentimento</strong>: retirar o consentimento para coletarmos informações do seu filho. Observe que isso resultará no encerramento da conta da criança.',
